"""Generated byte streams only; no third-party data or network calls."""

import io
from pathlib import Path
from urllib.error import HTTPError

import pytest

from nfl_prediction.data import downloads
from nfl_prediction.data.downloads import Downloader
from nfl_prediction.storage.database import Database


class Response(io.BytesIO):
    def __init__(self, body: bytes, *, length: int | None = None):
        super().__init__(body)
        self.headers = {
            "ETag": '"test-etag"',
            "Content-Length": str(len(body) if length is None else length),
        }


def test_conditional_cache_force_refresh_and_immutable_revisions(tmp_path, monkeypatch):
    db = Database(tmp_path)
    requests = []

    def respond(request, **_):
        requests.append(dict(request.header_items()))
        if len(requests) == 2:
            raise HTTPError(request.full_url, 304, "Not Modified", {}, None)
        return Response(b"first-version" if len(requests) == 1 else b"second-version")

    monkeypatch.setattr(downloads, "urlopen", respond)
    url = "https://example.com/test.parquet"
    first = Downloader(tmp_path, db).fetch(url, refresh=False)
    cached = Downloader(tmp_path, db).fetch(url, refresh=False)
    conditional = Downloader(tmp_path, db).fetch(url, refresh=True)
    updated = Downloader(tmp_path, db).fetch(url, refresh=True, force=True)
    assert cached == conditional == first
    assert requests[1]["If-none-match"] == '"test-etag"'
    assert "If-none-match" not in requests[2]
    assert updated.sha256 != first.sha256
    assert Path(first.path).read_bytes() == b"first-version"
    assert Path(updated.path).read_bytes() == b"second-version"
    db.close()


def test_incomplete_download_does_not_replace_cache(tmp_path, monkeypatch):
    db = Database(tmp_path)
    monkeypatch.setattr(downloads, "urlopen", lambda *_args, **_kw: Response(b"good"))
    url = "https://example.com/test.parquet"
    first = Downloader(tmp_path, db).fetch(url, refresh=False)
    monkeypatch.setattr(downloads, "urlopen", lambda *_args, **_kw: Response(b"short", length=100))
    with pytest.raises(ValueError, match="Incomplete"):
        Downloader(tmp_path, db).fetch(url, refresh=True, force=True)
    assert Downloader(tmp_path, db).fetch(url, refresh=False) == first
    assert not list((tmp_path / "raw").glob("*.part"))
    db.close()


def test_corrupt_raw_cache_fails_before_network(tmp_path, monkeypatch):
    db = Database(tmp_path)
    monkeypatch.setattr(downloads, "urlopen", lambda *_args, **_kw: Response(b"good"))
    url = "https://example.com/test.parquet"
    cached = Downloader(tmp_path, db).fetch(url, refresh=False)
    Path(cached.path).write_bytes(b"corrupted-test-fixture")
    with pytest.raises(ValueError, match="integrity"):
        Downloader(tmp_path, db).fetch(url, refresh=False)
    db.close()


def test_temporary_server_error_retries(tmp_path, monkeypatch):
    db = Database(tmp_path)
    attempts = []

    def respond(request, **_):
        attempts.append(1)
        if len(attempts) == 1:
            raise HTTPError(request.full_url, 503, "Unavailable", {}, None)
        return Response(b"good")

    monkeypatch.setattr(downloads, "urlopen", respond)
    monkeypatch.setattr(downloads.time, "sleep", lambda _: None)
    Downloader(tmp_path, db).fetch("https://example.com/test.parquet", refresh=False)
    assert len(attempts) == 2
    db.close()
